package com.amardokan.app.messaging\n\nimport android.app.NotificationChannel\nimport android.app.NotificationManager\nimport android.app.PendingIntent\nimport android.content.Context\nimport android.content.Intent\nimport android.os.Build\nimport androidx.core.app.NotificationCompat\nimport com.amardokan.app.MainActivity\nimport com.amardokan.app.R\nimport com.google.firebase.messaging.FirebaseMessagingService\nimport com.google.firebase.messaging.RemoteMessage\nimport timber.log.Timber\n\nclass FCMService : FirebaseMessagingService() {\n\n    override fun onMessageReceived(remoteMessage: RemoteMessage) {\n        Timber.d(\"FCM Message received from: ${remoteMessage.from}\")\n        Timber.d(\"Message data: ${remoteMessage.data}\")\n\n        // Handle notification\n        remoteMessage.notification?.let {\n            sendNotification(\n                title = it.title ?: \"Notification\",\n                body = it.body ?: \"\",\n                data = remoteMessage.data\n            )\n        }\n\n        // Handle data message\n        if (remoteMessage.data.isNotEmpty()) {\n            handleDataMessage(remoteMessage.data)\n        }\n    }\n\n    override fun onNewToken(token: String) {\n        Timber.d(\"FCM Token refreshed: $token\")\n        // Save token to Firestore\n        saveFCMTokenToFirestore(token)\n    }\n\n    private fun sendNotification(\n        title: String,\n        body: String,\n        data: Map<String, String>\n    ) {\n        val notificationManager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager\n\n        // Create notification channel for Android 8+\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {\n            val channel = NotificationChannel(\n                CHANNEL_ID,\n                \"আমার দোকান Notifications\",\n                NotificationManager.IMPORTANCE_HIGH\n            ).apply {\n                description = \"Notifications for আমার দোকান app\"\n            }\n            notificationManager.createNotificationChannel(channel)\n        }\n\n        // Create intent based on notification type\n        val intent = createIntentForNotification(data)\n        val pendingIntent = PendingIntent.getActivity(\n            this,\n            0,\n            intent,\n            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE\n        )\n\n        val notification = NotificationCompat.Builder(this, CHANNEL_ID)\n            .setContentTitle(title)\n            .setContentText(body)\n            .setSmallIcon(R.drawable.ic_notification)\n            .setAutoCancel(true)\n            .setContentIntent(pendingIntent)\n            .setPriority(NotificationCompat.PRIORITY_HIGH)\n            .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)\n            .build()\n\n        notificationManager.notify(System.currentTimeMillis().toInt(), notification)\n    }\n\n    private fun handleDataMessage(data: Map<String, String>) {\n        val notificationType = data[\"type\"]\n        Timber.d(\"Handling notification type: $notificationType\")\n\n        when (notificationType) {\n            \"login_request\" -> {\n                Timber.d(\"New login request notification\")\n                // App will fetch from Firestore when opened\n            }\n            \"payment_request\" -> {\n                Timber.d(\"New payment request notification\")\n                // App will fetch from Firestore when opened\n            }\n            \"sms_request\" -> {\n                Timber.d(\"New SMS request notification\")\n                // App will fetch from Firestore when opened\n            }\n            else -> {\n                Timber.d(\"Unknown notification type: $notificationType\")\n            }\n        }\n    }\n\n    private fun createIntentForNotification(data: Map<String, String>): Intent {\n        val intent = Intent(this, MainActivity::class.java)\n        intent.flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP\n\n        val notificationType = data[\"type\"]\n        when (notificationType) {\n            \"login_request\" -> {\n                intent.putExtra(\"screen\", \"login_requests\")\n                intent.putExtra(\"request_id\", data[\"request_id\"])\n            }\n            \"payment_request\" -> {\n                intent.putExtra(\"screen\", \"payment_requests\")\n                intent.putExtra(\"request_id\", data[\"request_id\"])\n            }\n            \"sms_request\" -> {\n                intent.putExtra(\"screen\", \"sms_requests\")\n                intent.putExtra(\"request_id\", data[\"request_id\"])\n            }\n        }\n\n        return intent\n    }\n\n    private fun saveFCMTokenToFirestore(token: String) {\n        try {\n            val auth = com.google.firebase.auth.FirebaseAuth.getInstance()\n            val user = auth.currentUser\n\n            if (user != null) {\n                // Update device FCM token in Firestore\n                val firestore = com.google.firebase.firestore.FirebaseFirestore.getInstance()\n                val userId = user.uid\n                val deviceId = getDeviceId()\n\n                firestore.collection(\"devices\")\n                    .whereEqualTo(\"user_id\", userId)\n                    .whereEqualTo(\"device_id\", deviceId)\n                    .get()\n                    .addOnSuccessListener { result ->\n                        if (!result.isEmpty) {\n                            val deviceDoc = result.documents[0]\n                            deviceDoc.reference.update(\"fcm_token\", token)\n                                .addOnSuccessListener {\n                                    Timber.d(\"FCM token updated in Firestore\")\n                                }\n                                .addOnFailureListener { e ->\n                                    Timber.e(e, \"Failed to update FCM token\")\n                                }\n                        }\n                    }\n                    .addOnFailureListener { e ->\n                        Timber.e(e, \"Failed to fetch device\")\n                    }\n            }\n        } catch (e: Exception) {\n            Timber.e(e, \"Error saving FCM token\")\n        }\n    }\n\n    private fun getDeviceId(): String {\n        return android.provider.Settings.Secure.getString(\n            contentResolver,\n            android.provider.Settings.Secure.ANDROID_ID\n        )\n    }\n\n    companion object {\n        private const val CHANNEL_ID = \"amar_dokan_notifications\"\n    }\n}\n"}}]
